// docs/芸能人マスタ.xlsx を1度だけパースしたもの(scripts/kins.data.ts と同じ方式)。
// 元ファイルは KIN列が各グループの先頭行にしか入っておらず(結合セルではなく空欄)、さらに
// KINごとに「人物名/生年月日/分野」の見出し行が挟まる構造だったので、前方補完と見出し行の
// 除外を行ったうえで KIN ごとにまとめている。生年月日はExcelシリアル値と「1889年3月7日」形式の
// テキストが混在していたため、いずれも YYYY-MM-DD へ正規化した。
//
// データ品質メモ(2026-08-17 時点、ユーザー確認のうえ「マスタの通り」に取り込んでいる):
//  - 生年月日から utils/mayaCalc.ts の dateToKin() で計算したKINが、マスタのKIN列と一致しない
//    レコードが 114件(2.9%)ある。内訳はうるう年3〜12月生まれで1ズレ44件 / 1900年以前6件 /
//    その他66件(差は最大157とばらばらで、明らかな誤記)。表示では生年月日も出すため、
//    該当者は「生年月日とKINが合わない」状態で見えることになる。
//  - 同一人物名が異なるKINに載っているものが32件。うち生年月日まで同じものもあり、
//    どちらかが誤りだが判別できないため両方残している。
//  - 生年月日が空欄のレコードが2件あった(birthdate: '')。表示側で日付を省く。
//    うち KIN16 の「マリーナ・アブラ」(氏名も途中で切れていた)は 2026-08-17 にユーザー提供の
//    正しい行「マリーナ・アブラモヴィッチ / 1946-11-30 / 現代美術家・パフォーマンスアーティスト」
//    へ修正済み。残る1件は KIN193「ナイル・ホーラ」。
//  - KIN16(12→15件)と KIN207(9→15件)は、元xlsxの内容に漏れがあったため 2026-08-17 に
//    ユーザー提供のリストで全面差し替え済み。xlsxを再パースすると戻ってしまうので注意。
//  - 「芸能人マスタ」だが歴史上の人物(鳥羽天皇/ダ・ヴィンチ/織田信長など)も含む。
//    1582年以前はグレゴリオ暦以前のため、そもそもKINの計算前提が成立しない。
export interface CelebrityEntry {
  name: string
  birthdate: string // YYYY-MM-DD。マスタに生年月日が無い2件のみ空文字
  field: string // 「俳優・歌手」など自由文
}

export interface CelebritySeed {
  index: number // 1-260、KinInfo.kin と同じ(SEALS/TONESのような0始まりではない)
  celebrities: CelebrityEntry[]
}

